using Microsoft.Playwright.NUnit;using NUnit.Framework;using NUnit.Framework.Interfaces;using SoftwareTestingExample.Utilities;
namespace SoftwareTestingExample.Tests;
public class UiTest:PageTest
{
 [SetUp] public async Task StartTracingAsync(){Page.SetDefaultTimeout(TestConfig.DefaultTimeoutMilliseconds);Page.SetDefaultNavigationTimeout(TestConfig.DefaultTimeoutMilliseconds);TestLogger.Log("test.started");await Context.Tracing.StartAsync(new(){Title=$"{TestContext.CurrentContext.Test.ClassName}.{TestContext.CurrentContext.Test.Name}",Screenshots=true,Snapshots=true,Sources=true});}
 [TearDown] public async Task CaptureDiagnosticsAsync(){var failed=TestContext.CurrentContext.Result.Outcome.Status==TestStatus.Failed;var dir=Path.Combine(TestContext.CurrentContext.WorkDirectory,"TestResults","FailureArtifacts");var name=$"{TestContext.CurrentContext.Test.ClassName}.{TestContext.CurrentContext.Test.Name}";TestLogger.Log(failed?"test.failed":"test.passed",failed?"Error":"Information",new{TestContext.CurrentContext.Result.Message});try{if(failed){Directory.CreateDirectory(dir);await Page.ScreenshotAsync(new(){Path=Path.Combine(dir,$"{name}.png"),FullPage=true});await Context.Tracing.StopAsync(new(){Path=Path.Combine(dir,$"{name}.zip")});}else await Context.Tracing.StopAsync();}catch(Exception e){TestLogger.Log("failure.diagnostics.incomplete","Warning",exception:e);}}
}